SELECT id, class, subtype, ST_AsGeoJSON(geometry) AS geojson
FROM lisbon_buildings
WHERE ST_Intersects(
        geometry,
        ST_MakeLine(ST_Point(-9.200, 38.700), ST_Point(-9.100, 38.800))
      );

SELECT id, names.primary AS name, basic_category
FROM lisbon_places
WHERE ST_Within(
        geometry,
        ST_MakeEnvelope(-9.090, 38.760, -9.070, 38.780)
      );

SELECT SUM(
           ST_Area(
             ST_Transform(geometry, 'EPSG:4326', 'EPSG:3763', always_xy := true)
           )
         ) AS total_residential_area_m2
FROM lisbon_buildings
WHERE subtype = 'residential'
  AND ST_DWithin_Spheroid(geometry, ST_Point(-9.135, 38.775), 1000);
